import{_ as n,c as o,o as s,j as e,ag as r,a as t}from"./chunks/framework.bCALENAD.js";const i="/assets/settings.DP7yd7eY.png",y=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"instructions/settings.md","filePath":"en/instructions/settings.md","lastUpdated":1720814184000}'),h={name:"instructions/settings.md"};function l(d,a,u,c,p,g){return s(),o("div",null,[...a[0]||(a[0]=[e("h1",{id:"settings",tabindex:"-1"},[t("Settings "),e("a",{class:"header-anchor",href:"#settings","aria-label":'Permalink to "Settings"'},"​")],-1),e("p",null,[e("img",{src:i,alt:"Latest test",align:"right"})],-1),e("p",null,[t("Clicking on the "),e("strong",null,"settings-icon"),t(" ⚙️ opens the settings page. You can find an example on the right.")],-1),e("p",null,"In this menu you can find settings as well as functions like exporting tests.",-1),e("p",null,"To make the design clearer, the settings related to the internet can be found in the first 4 lines.",-1),e("p",null,"All options related to speed tests can be found in the 2nd box. Here you can e.g. set the frequency of the tests or select a server.",-1),e("p",null,"In the 3rd box you can find settings related to the interface. Here you can change the language or the view.",-1),e("br",{clear:"both"},null,-1),r('<h2 id="internet-related-settings" tabindex="-1">Internet related settings <a class="header-anchor" href="#internet-related-settings" aria-label="Permalink to &quot;Internet related settings&quot;">​</a></h2><p>Here are settings that relate to your optimal Internet.</p><div class="tip custom-block"><p class="custom-block-title">What&#39;s the point?</p><p>MySpeed uses colored icons to symbolize the quality of your internet connection. If you enter these values here, MySpeed will show you by icons if your internet is good, medium or bad.</p></div><h3 id="🏓-ping" tabindex="-1">🏓 Ping <a class="header-anchor" href="#🏓-ping" aria-label="Permalink to &quot;🏓 Ping&quot;">​</a></h3><p>The ping is a value that shows the duration of the connection between your computer and the internet in <strong>ms</strong>.<br> The faster (i.e. lower), the better.</p><h3 id="⬆️-up-speed" tabindex="-1">⬆️ Up-Speed <a class="header-anchor" href="#⬆️-up-speed" aria-label="Permalink to &quot;⬆️ Up-Speed&quot;">​</a></h3><p>The up-speed is the speed at which your computer sends data. The higher the value, the better.</p><h3 id="⬇️-down-speed" tabindex="-1">⬇️ Down-Speed <a class="header-anchor" href="#⬇️-down-speed" aria-label="Permalink to &quot;⬇️ Down-Speed&quot;">​</a></h3><p>The down-speed is the speed at which your computer receives data. The higher the value, the better.</p><h3 id="🛠️-optimal-values" tabindex="-1">🛠️ Optimal values <a class="header-anchor" href="#🛠️-optimal-values" aria-label="Permalink to &quot;🛠️ Optimal values&quot;">​</a></h3><p>If you don&#39;t know what values you should enter here, you can use this button. MySpeed will then try to determine the optimal values for you.</p><h2 id="speedtest-settings" tabindex="-1">Speedtest settings <a class="header-anchor" href="#speedtest-settings" aria-label="Permalink to &quot;Speedtest settings&quot;">​</a></h2><h3 id="🖥️-change-server" tabindex="-1">🖥️ Change server <a class="header-anchor" href="#🖥️-change-server" aria-label="Permalink to &quot;🖥️ Change server&quot;">​</a></h3><p>MySpeed chooses the next server automatically at startup. But if you find a closer server, you can select it here. You can choose one from the list or enter an ID. You can read more about this <a href="https://www.ookla.com/network" target="_blank" rel="noreferrer">here</a>.</p><h3 id="🔑-change-password" tabindex="-1">🔑 Change password <a class="header-anchor" href="#🔑-change-password" aria-label="Permalink to &quot;🔑 Change password&quot;">​</a></h3><p>Is your MySpeed instance public and you don&#39;t want others or only authorized people to see your internet speed? Then you can protect MySpeed with a password here, which has to be entered when visiting the site.</p><h3 id="🕒-set-frequency" tabindex="-1">🕒 Set frequency <a class="header-anchor" href="#🕒-set-frequency" aria-label="Permalink to &quot;🕒 Set frequency&quot;">​</a></h3><p>Here you can set the frequency in which MySpeed performs your tests. This setting can be relevant for slower connections.</p><h3 id="⏸️-pause-speed-tests" tabindex="-1">⏸️ Pause speed tests <a class="header-anchor" href="#⏸️-pause-speed-tests" aria-label="Permalink to &quot;⏸️ Pause speed tests&quot;">​</a></h3><p>Do you have to upload an important document right now and MySpeed is affecting your internet speed a lot? Then you can pause it here for a certain time. This can be relevant especially for slow connections.</p><h3 id="🌐-integrations" tabindex="-1">🌐 Integrations <a class="header-anchor" href="#🌐-integrations" aria-label="Permalink to &quot;🌐 Integrations&quot;">​</a></h3><p>MySpeed uses integrations to notify you when your internet is down. You have services like Discord, Telegram, or Gotify to choose from. If you want to process the data yourself, you can also specify a webhook and have all events sent to you.</p><h2 id="interface-settings" tabindex="-1">Interface settings <a class="header-anchor" href="#interface-settings" aria-label="Permalink to &quot;Interface settings&quot;">​</a></h2><h3 id="📅-set-period" tabindex="-1">📅 Set period <a class="header-anchor" href="#📅-set-period" aria-label="Permalink to &quot;📅 Set period&quot;">​</a></h3><p>Here you can define how many tests will be displayed in the specified period. You can choose between the last 24 and 48 hours as well as the last 7 or 30 days. If you select one of the last two, you will be shown averages to make the interface clearer.</p><h3 id="📤-export-tests" tabindex="-1">📤 Export tests <a class="header-anchor" href="#📤-export-tests" aria-label="Permalink to &quot;📤 Export tests&quot;">​</a></h3><p>Do you want to be sure and download your tests to your computer? Then you can export your tests here.</p><h3 id="🌍-change-language" tabindex="-1">🌍 Change language <a class="header-anchor" href="#🌍-change-language" aria-label="Permalink to &quot;🌍 Change language&quot;">​</a></h3><p>MySpeed is currently available in English and German languages. With this option you can change the language. Do you want to participate and translate MySpeed into another language? Then have a look <a href="https://crowdin.com/project/myspeed" target="_blank" rel="noreferrer">here</a>.</p><h3 id="📊-change-view" tabindex="-1">📊 Change view <a class="header-anchor" href="#📊-change-view" aria-label="Permalink to &quot;📊 Change view&quot;">​</a></h3><p>MySpeed offers you two views. The first one is the default view you already know. The second one is the <strong>Test Statistics</strong>. Here you can see all tests with the help of widgets and diagrams.</p><h3 id="i️-information" tabindex="-1">ℹ️ Information <a class="header-anchor" href="#i️-information" aria-label="Permalink to &quot;ℹ️ Information&quot;">​</a></h3><p>This section shows you information about your MySpeed instance. Nothing important, just a little info. 😃</p>',33)])])}const m=n(h,[["render",l]]);export{y as __pageData,m as default};
